nt density"}, {"id": "f28f1126-91e6-47a7-a017-e612919a2361", "type": "concept", "title": "Food access and affordability"}]}, {"id": "03f45b6b-fdfb-4e09-8e43-b143b9110203", "type": "subtopic", "title": "Supplement vs. food-first decisions", "description": "Students practice deciding when food is sufficient and when supplementation is evidence-based.", "children": [{"id": "5bafe8aa-fdee-403f-a96c-35114cceafa8", "type": "concept", "title": "Indications for supplementation"}, {"id": "ae895f12-f173-497b-ad11-73e18c23d4ce", "type": "concept", "title": "Dose, form, and safety"}, {"id": "2e6b6f58-9ab4-4765-81c1-431b465f2843", "type": "concept", "title": "Interaction and toxicity risks"}]}]}, {"id": "2c769344-7dc9-42d0-bced-b8c6148d1128", "type": "topic", "title": "Hydration, Electrolytes, and Thermoregulation", "description": "Hydration planning connects performance, safety, sweat losses, heat stress, and individualized strategy.", "children": [{"id": "cc0aa0e2-c9b5-4749-b173-54ef7f50549f", "type": "subtopic", "title": "Fluid balance and sweat rate", "description": "Students learn to estimate fluid needs using body mass change, sweat rate, and environment.", "children": [{"id": "b445f286-8b53-4942-a6fd-6b6b4c6d21ba", "type": "concept", "title": "Euhydration and dehydration"}, {"id": "874db4a5-da83-40ce-86a1-151677699b39", "type": "concept", "title": "Sweat testing basics"}, {"id": "3a8ecd63-0ce2-4905-bdbd-0f100d21a2ac", "type": "concept", "title": "Heat, humidity, clothing, and acclimatization"}]}, {"id": "39405c6d-29be-4dc7-b407-6c70e090f1ba", "type": "subtopic", "title": "Electrolytes and sodium strategy", "description": "Students understand when electrolytes matter and why one-size advice fails.", "children": [{"id": "4da017ab-9bf6-4703-a067-ea5d1ea04f5c", "type": "concept", "title": "Sodium losses and replacement"}, {"id": "7a96f7fa-968a-470d-b2c3-aaae57e9040d", "type": "concept", "title": "Hyponatremia risk"}, {"id": "0af18ebb-0458-49e2-9ca4-dd4839ffa326", "type": "concept", "title": "Cramps, thirst, and practical signals"}]}, {"id": "8c1c8415-3357-42bc-a52e-a0dd9abb0f2a", "type": "subtopic", "title": "Competition hydration plans", "description": "Students translate physiology into pre-, during-, and post-exercise plans.", "children": [{"id": "f0d90287-fbde-49e3-9e94-201c0d4c5b3d", "type": "concept", "title": "Prehydration"}, {"id": "e6f73025-41b9-49d2-8ab9-24b9f320051b", "type": "concept", "title": "Fluid access during events"}, {"id": "2a9d37ee-4636-42a1-8219-a20a3a8da157", "type": "concept", "title": "Rehydration after exercise"}]}]}, {"id": "250d318f-d497-4a07-a26b-4a7bac874c0f", "type": "topic", "title": "Energy Balance, Energy Availability, and RED-S", "description": "Energy balance is not just weight math; energy availability determines whether the body can train, adapt, menstruate, maintain bone, and recover.", "children": [{"id": "9d7aac3c-7f06-4dc5-abc9-81c87cdd8725", "type": "subtopic", "title": "Energy balance concepts", "description": "Students learn the difference between intake, expenditure, and the body's adaptive responses.", "children": [{"id": "01a62f0d-2838-4186-88b4-f6d1822fd352", "type": "concept", "title": "Energy intake vs. expenditure"}, {"id": "6dda5831-a9f4-4c10-b4be-3b3414c32388", "type": "concept", "title": "Adaptive thermogenesis"}, {"id": "97907d9f-3960-4f06-84d7-ce49c11d36d7", "type": "concept", "title": "Within-day energy deficits"}]}, {"id": "3f21b838-2d83-4c18-b17b-a95dbcf357c0", "type": "subtopic", "title": "Low energy availability and RED-S", "description": "Students learn how chronic underfueling harms health and performance.", "children": [{"id": "67866fa6-947b-42c7-a409-b37c9c03d241", "type": "concept", "title": "Relative Energy Deficiency in Sport"}, {"id": "4df76a37-9305-45ee-ac09-d556ee4bb157", "type": "concept", "title": "Menstrual, endocrine, bone, immune, and mood effects"}, {"id": "fbaef5b1-1810-4bf0-bf87-b65276f37040", "type": "concept", "title": "Screening and referral"}]}, {"id": "e1160f2e-37d0-4535-aec8-d7523ac5ceaa", "type": "subtopic", "title": "Periodized energy availability", "description": "Students learn to match energy intake to training demands without normalizing chronic restriction.", "children": [{"id": "17240158-a20a-4b39-8607-0ec2d2ad90aa", "type": "concept", "title": "Heavy training days"}, {"id": "05857f8d-3e7a-46c1-9e58-0d5606465554", "type": "concept", "title": "Recovery and rest days"}, {"id": "e1465759-90a5-4990-806a-538eaf2f4d2d", "type": "concept", "title": "Growth, adolescence, and injury recovery"}]}]}, {"id": "64081d20-a7ee-4cbb-91e8-438e3e6d4050", "type": "topic", "title": "Nutrient Timing for Training, Competition, and Recovery", "description": "Timing helps students use nutrition strategically around the stress of exercise rather than treating daily intake as a flat average.", "children": [{"id": "bb4c042c-713a-4b8d-8475-2903d972732d", "type": "subtopic", "title": "Pre-exercise fueling", "description": "Students learn how to choose meals and snacks that support performance without gastrointestinal distress.", "children": [{"id": "7c797f59-35ac-4e1b-ac65-7813060abf55", "type": "concept", "title": "Meal timing windows"}, {"id": "14126ecc-c447-4342-ad11-a143bbd0d2a7", "type": "concept", "title": "Carbohydrate availability"}, {"id": "13eae9ca-9653-4a8c-ba00-83b967e7c7fb", "type": "concept", "title": "GI tolerance and food choices"}]}, {"id": "6f06274d-5bc3-4ade-b46e-a05a7dd7dcbe", "type": "subtopic", "title": "Fueling during exercise", "description": "Students learn when during-session carbohydrate, fluids, and sodium improve outcomes.", "children": [{"id": "55ce5609-4bf4-44fa-aa84-5bd2a49c2497", "type": "concept", "title": "Exercise duration thresholds"}, {"id": "bc913771-8b2b-46a2-8002-cb2d506a7be3", "type": "concept", "title": "Carbohydrate absorption and multiple transporters"}, {"id": "4abb9b04-5982-48b4-ab2e-761845273cc1", "type": "concept", "title": "Practice in training"}]}, {"id": "b426d856-d593-4328-98d2-4b6cc089c146", "type": "subtopic", "title": "Post-exercise recovery", "description": "Students learn to prioritize recovery inputs based on the next training demand.", "children": [{"id": "4823bca6-3fc5-4be1-8bec-3ffa4278a3b1", "type": "concept", "title": "Glycogen resynthesis"}, {"id": "07999af3-864e-43b1-bb7f-d5c0b2389455", "type": "concept", "title": "Protein distribution"}, {"id": "29b19f62-da77-4f24-958c-90ba2fccc9fb", "type": "concept", "title": "Rehydration and sleep linkage"}]}]}, {"id": "49439d3c-ff63-45bb-adb0-d46b49b1f122", "type": "topic", "title": "Performance Supplements, Ergogenic Aids, and Anti-Doping", "description": "This topic gives students a skeptical, evidence-based framework for supplements, benefits, risks, contamination, and sport rules.", "children": [{"id": "4ad63544-4761-4d03-a9c0-8d32905a2eee", "type": "subtopic", "title": "Evidence-supported ergogenic aids", "description": "Students learn which supplements have plausible benefits for specific tasks.", "children": [{"id": "3290e018-9791-4fc1-aa2a-5857cb94459a", "type": "concept", "title": "Caffeine"}, {"id": "d06e0622-df06-4748-87a2-eebdf1460e83", "type": "concept", "title": "Creatine monohydrate"}, {"id": "c19c4721-a896-4d4d-8828-b0ddc868bb03", "type": "concept", "title": "Nitrate, beta-alanine, and bicarbonate"}]}, {"id": "bd34553c-307e-4d28-8c5b-fe995630599e", "type": "subtopic", "title": "Safety, quality, and contamination", "description": "Students learn that supplement risk is both biological and regulatory.", "children": [{"id": "2141c8e5-b7c3-404a-be44-59ee0650c635", "type": "concept", "title": "Third-party testing"}, {"id": "35d180c5-9628-4b2b-a80d-aa508a0dff75", "type": "concept", "title": "Label accuracy"}, {"id": "041acfc9-33dd-4044-9a25-18849620547f", "type": "concept", "title": "Adverse effects and contraindications"}]}, {"id": "79a8e832-e093-4f1f-9cae-8ce95a1eab1f", "type": "subtopic", "title": "Anti-doping literacy", "description": "Students learn to protect athletes from preventable eligibility and health harms.", "children": [{"id": "6c30836c-d5e3-4f5e-ad6e-5e4169a6ce69", "type": "concept", "title": "USADA/WADA principles"}, {"id": "a63df23f-5e99-44fa-a465-7e5855fd3d4c", "type": "concept", "title": "Strict liability"}, {"id": "eb6477f6-45da-4cbb-8ea3-02abf2faf6e8", "type": "concept", "title": "Medication and supplement checks"}]}]}, {"id": "3db20a8d-c50b-46a6-b4a2-83f7039a1420", "type": "topic", "title": "Body Composition Assessment and Interpretation", "description": "Body composition is useful only when measured and communicated carefully. Students learn methods, assumptions, error, and ethical interpretation.", "children": [{"id": "cb41b2eb-c3d8-44fb-94bf-6eab0e527d71", "type": "subtopic", "title": "Assessment methods", "description": "Students compare tools based on validity, reliability, cost, and context.", "children": [{"id": "aa754ca4-455b-4ece-ab4f-d1dafa2061cf", "type": "concept", "title": "Skinfolds and circumference"}, {"id": "859918d3-da1b-49c1-92c9-69800e30abeb", "type": "concept", "title": "Bioelectrical impedance"}, {"id": "74654757-5972-4afa-9fff-016185a7a4de", "type": "concept", "title": "DXA and air displacement"}]}, {"id": "aae18660-d712-4943-911f-4b97811faf6d", "type": "subtopic", "title": "Interpreting change", "description": "Students learn to distinguish real change from measurement noise.", "children": [{"id": "7f49dede-644c-43ad-bb08-833b3d36e069", "type": "concept", "title": "Technical error of measurement"}, {"id": "7f697cc5-39c7-4615-ba76-40d698ed6eb9", "type": "concept", "title": "Hydration and glycogen effects"}, {"id": "25fac7d8-073f-46dd-ab11-4dbd48db2c0f", "type": "concept", "title": "Meaningful vs. trivial change"}]}, {"id": "21f9e210-04e5-463f-a172-1b8604204dce", "type": "subtopic", "title": "Ethical communication", "description": "Students learn to avoid weight stigma and appearance-centered harm.", "children": [{"id": "e86b1f74-596d-48c0-88f5-bd282045d48b", "type": "concept", "title": "Consent and privacy"}, {"id": "21a507ca-1146-429d-b5e8-8b140f6fa533", "type": "concept", "title": "Performance vs. health framing"}, {"id": "e71e6762-2e11-423f-b0f8-4fee62c297fb", "type": "concept", "title": "Language that supports autonomy"}]}]}, {"id": "9743075b-ea29-44ea-81ca-be24a6b35df2", "type": "topic", "title": "Weight Management, Muscle Gain, and Fat Loss", "description": "This topic examines body-mass change through health, performance, psychology, and sustainability rather than quick-fix dieting.", "children": [{"id": "29539c1b-98e5-4435-b76b-35b8a225cb27", "type": "subtopic", "title": "Fat loss principles", "description": "Students learn to create realistic energy deficits while protecting training and health.", "children": [{"id": "17e57c92-7758-4538-889b-ff82de48a8b6", "type": "concept", "title": "Rate of loss"}, {"id": "f736e5cd-e11c-460a-95be-6094c94080fa", "type": "concept", "title": "Protein and resistance training"}, {"id": "216c4f96-851c-4dfb-9fd3-1dcdcada56a1", "type": "concept", "title": "Hunger, adherence, and diet breaks"}]}, {"id": "f29ee869-a80e-4d1e-ba4c-60eea32b5852", "type": "subtopic", "title": "Muscle gain principles", "description": "Students learn how energy surplus, protein, and training interact for hypertrophy.", "children": [{"id": "7e340bd7-38d7-40d2-af92-31ff7d5b6069", "type": "concept", "title": "Caloric surplus range"}, {"id": "69b1c895-8eb9-4130-98a5-6427da974381", "type": "concept", "title": "Protein distribution"}, {"id": "653b2b66-2d2d-4612-b972-7b871ecec155", "type": "concept", "title": "Training stimulus and recovery"}]}, {"id": "cc3cbffc-f76d-45a3-8c14-060d0876696a", "type": "subtopic", "title": "Maintenance and relapse prevention", "description": "Students learn that long-term outcomes depend on habits, environment, and monitoring.", "children": [{"id": "f58114d2-9647-489b-bb2d-13030cbdfc14", "type": "concept", "title": "Self-monitoring options"}, {"id": "7d5a2125-578f-41e8-9e83-6a03f355d9d5", "type": "concept", "title": "Flexible restraint"}, {"id": "bdbaccef-8827-4450-b3b4-1072a938093e", "type": "concept", "title": "Sleep, stress, and social support"}]}]}, {"id": "3138613b-648f-465e-94c0-7638f3adead0", "type": "topic", "title": "Special Populations and Life-Course Nutrition", "description": "Nutrition needs change across age, physiology, health status, culture, and sport context. Students learn to adapt recommendations while respecting scope of practice.", "children": [{"id": "d30fb374-39ff-4199-a8f3-3d2649866334", "type": "subtopic", "title": "Youth, collegiate, and masters athletes", "description": "Students learn how growth, maturation, and aging change nutrition priorities.", "children": [{"id": "976dc2b2-787d-4024-81a5-b74ade3396e4", "type": "concept", "title": "Growth and development"}, {"id": "8aad4d45-241a-4617-81ee-6e96c0780f5e", "type": "concept", "title": "Bone health"}, {"id": "c18d0633-06eb-41f3-93b3-a315c0dbe9c8", "type": "concept", "title": "Sarcopenia and recovery"}]}, {"id": "81345dd8-023b-446c-bf52-71a1ecdf0cd5", "type": "subtopic", "title": "Pregnancy, disability, and clinical considerations", "description": "Students learn when exercise nutrition intersects with medical nutrition therapy.", "children": [{"id": "02a2d264-692a-4d06-a758-bfd4d2785551", "type": "concept", "title": "Pregnancy and postpartum basics"}, {"id": "042ff88b-78da-4dfc-909c-cb8a7bf2dcfc", "type": "concept", "title": "Diabetes and cardiovascular risk"}, {"id": "a89c9a34-c0f5-450d-b2bb-ed2352ca9f22", "type": "concept", "title": "Adaptive sport considerations"}]}, {"id": "f77962a7-cb00-4a11-ba26-95437dac2120", "type": "subtopic", "title": "Plant-based and culturally diverse diets", "description": "Students learn to support performance without flattening culture or personal values.", "children": [{"id": "03c7eaa7-df21-4b9d-88ba-2e8e1e4732ab", "type": "concept", "title": "Protein planning"}, {"id": "31dc492b-d198-42db-9bc5-a6ee8842474f", "type": "concept", "title": "Iron, B12, calcium, vitamin D, and omega-3"}, {"id": "c2180738-e38a-4741-af9a-151d9cc9155a", "type": "concept", "title": "Cultural food patterns"}]}]}, {"id": "2bd4ef05-a0dc-4a79-a7d8-3f71da8773e9", "type": "topic", "title": "Disordered Eating, Eating Disorders, and Athlete Mental Health", "description": "This topic helps future kinesiology professionals recognize risk, reduce harm, and refer early rather than trying to treat complex disorders alone.", "children": [{"id": "d533a32e-59e8-4757-99c3-89df3ab61464", "type": "subtopic", "title": "Risk factors in sport and fitness culture", "description": "Students learn why some environments amplify body dissatisfaction and restrictive behaviors.", "children": [{"id": "b50914c7-af43-4ac3-8aa5-95c7e56ac9f5", "type": "concept", "title": "Weight-class and aesthetic sports"}, {"id": "6488e862-74f6-4616-8872-2015cd868ef1", "type": "concept", "title": "Coach and peer pressures"}, {"id": "d8fcd293-2f79-41b2-ba37-704f2d4bf72c", "type": "concept", "title": "Social media and tracking apps"}]}, {"id": "da79fcf9-4fa5-4480-8587-b71e6212da85", "type": "subtopic", "title": "Warning signs and screening", "description": "Students learn signs that deserve compassionate follow-up and referral.", "children": [{"id": "62e13d7f-f4d7-45a8-99e2-bae69921e7a9", "type": "concept", "title": "Behavioral, physical, and performance signs"}, {"id": "f38187c3-6a02-4cff-b709-d022da344475", "type": "concept", "title": "RED-S overlap"}, {"id": "bc4e58d0-cf4e-4113-b216-ec80e424723e", "type": "concept", "title": "Validated screening tools"}]}, {"id": "bfffcec4-2973-4ba7-868d-b7241d003fa7", "type": "subtopic", "title": "Referral and supportive communication", "description": "Students practice language that supports safety without shame or diagnosis overreach.", "children": [{"id": "0edbe1c3-bd30-495f-9524-2af51a853ef4", "type": "concept", "title": "Trauma-informed conversation basics"}, {"id": "90717fb5-ff6d-4b16-a0ba-753e9d0f7bc5", "type": "concept", "title": "Interdisciplinary care"}, {"id": "5ea372e3-1429-4dd9-a3e8-e3b15854e268", "type": "concept", "title": "Emergency warning signs"}]}]}, {"id": "6446ad21-aeec-4854-93c3-a7a878997e02", "type": "topic", "title": "Behavior Change, Coaching Communication, and Food Environments", "description": "Nutrition knowledge only matters if it can be applied in real lives. Students learn behavior-change tools that respect autonomy and context.", "children": [{"id": "4987e2a0-6f81-4511-b182-2e66e19ca86e", "type": "subtopic", "title": "Behavior-change frameworks", "description": "Students learn practical models for helping people turn goals into habits.", "children": [{"id": "55e62831-4075-4723-be75-5d404d9284a0", "type": "concept", "title": "Motivational interviewing spirit"}, {"id": "0275ee6d-c11a-4a73-a1f6-4930c8434d37", "type": "concept", "title": "Self-determination theory"}, {"id": "af4114cb-bb86-4a18-a495-ce35bf7e1c77", "type": "concept", "title": "SMART goals and implementation intentions"}]}, {"id": "efe2466a-ce64-470a-98c4-aac40c03a2cd", "type": "subtopic", "title": "Food environment and access", "description": "Students learn that choices are shaped by time, money, culture, stress, and availability.", "children": [{"id": "bc4512e3-583d-4604-8071-e1d2c95e5df2", "type": "concept", "title": "Food insecurity"}, {"id": "72d6e962-a152-4e4c-b039-f6be276f1db2", "type": "concept", "title": "Campus and travel nutrition"}, {"id": "d0849afd-c41b-4b94-af5b-ce9b577b50ae", "type": "concept", "title": "Convenience and meal planning"}]}, {"id": "50a08c61-97d4-4c03-8f85-146ef2124761", "type": "subtopic", "title": "Communication and coaching practice", "description": "Students learn to translate evidence into clear, nonjudgmental guidance.", "children": [{"id": "30592a04-1055-491b-a9cb-eff538f29fb9", "type": "concept", "title": "Plain-language explanations"}, {"id": "21ea2fc5-5ba6-40f2-9639-6696aba50491", "type": "concept", "title": "Collaborative problem-solving"}, {"id": "dde578fc-ea81-467f-a69a-0ba59b8200d5", "type": "concept", "title": "Myth correction without shaming"}]}]}, {"id": "ba1a8049-093a-4faa-9d59-d6d1a2132c34", "type": "topic", "title": "Applied Meal Planning and Periodized Fueling", "description": "This topic turns science into plans for training weeks, competition days, recovery blocks, and travel realities.", "children": [{"id": "8ed13bb3-c102-45a1-910a-cde88e29f60d", "type": "subtopic", "title": "Daily meal planning for active people", "description": "Students learn to build balanced menus that meet energy, macro, micro, and practical needs.", "children": [{"id": "4f7a3514-ca3f-42e5-8fbf-46975549bc9a", "type": "concept", "title": "Plate models and portion frameworks"}, {"id": "26547fa0-3469-4851-a352-f7c8489eadc9", "type": "concept", "title": "Budget and schedule constraints"}, {"id": "aaf43d2e-142c-49e7-ae60-2b0655762981", "type": "concept", "title": "Meal prep and dining hall strategies"}]}, {"id": "5f5d80a8-b6e3-4e0f-b3f3-d58905c7e831", "type": "subtopic", "title": "Periodized fueling", "description": "Students match nutrition strategy to training phase and outcome goal.", "children": [{"id": "7cc6e450-873d-4b02-be2b-90131f07432d", "type": "concept", "title": "Base, build, taper, and competition phases"}, {"id": "986b33e3-c1c8-44be-8b68-cf65deebcf60", "type": "concept", "title": "Fuel for the work required"}, {"id": "997a0608-343e-4c6e-b3f0-4b871d35916e", "type": "concept", "title": "Recovery blocks and injury periods"}]}, {"id": "19565fb2-db7b-4b9d-a312-6904b4f5531e", "type": "subtopic", "title": "Competition and travel logistics", "description": "Students learn that execution often fails because of planning, not knowledge.", "children": [{"id": "14d5b766-1d92-4408-9746-88bff550618a", "type": "concept", "title": "Packing lists and backup foods"}, {"id": "4f1fb121-c1ee-4e3a-bd7d-156bcd652e09", "type": "concept", "title": "Restaurant and hotel strategies"}, {"id": "a8efcb0c-7fb0-4515-a568-ddb4d2b79368", "type": "concept", "title": "Jet lag, GI risk, and routine preservation"}]}]}, {"id": "095ce685-823a-4e15-89bf-3e92287bf328", "type": "topic", "title": "Applied Case Integration, Data, and Professional Practice", "description": "The capstone topic asks students to synthesize assessment, evidence, ethics, and communication into real kinesiology nutrition cases.", "children": [{"id": "6f3e920a-cfc9-4951-8977-92695f1fe953", "type": "subtopic", "title": "Case-based nutrition planning", "description": "Students practice reasoning from needs, constraints, and goals rather than copying generic templates.", "children": [{"id": "f3b3de5b-9585-4788-abea-8970d22cbcca", "type": "concept", "title": "Endurance, strength, team-sport, and general-fitness cases"}, {"id": "4fd5cd62-439a-4aeb-9608-ac5d7c76f0d8", "type": "concept", "title": "Goal hierarchy"}, {"id": "917967d5-47eb-47c7-9e0d-4d54041f27b9", "type": "concept", "title": "Monitoring and adjustment"}]}, {"id": "f3023726-e1bb-45e0-936b-4af4cfd54f00", "type": "subtopic", "title": "Data tracking and evaluation", "description": "Students learn to use metrics responsibly without overmeasuring or creating harm.", "children": [{"id": "84333e13-a013-4949-ace7-783ac6010c87", "type": "concept", "title": "Performance, recovery, body composition, and symptom markers"}, {"id": "7c7d1ee9-ecb4-4480-81d8-4c69f0f413ff", "type": "concept", "title": "Intake tracking pros and cons"}, {"id": "bdfc4c65-4fbb-4ad3-a2a6-9104a79f9cca", "type": "concept", "title": "Data privacy"}]}, {"id": "e0180da9-e716-45da-85ed-0852db39e0da", "type": "subtopic", "title": "Professional documentation", "description": "Students learn to communicate recommendations clearly and defensibly.", "children": [{"id": "c5a9a9d9-23cd-4fc7-a600-8b0168eaf4b4", "type": "concept", "title": "Brief nutrition plans"}, {"id": "bbe1e264-8cef-4729-92ad-2be56ca4b6e9", "type": "concept", "title": "Referral notes"}, {"id": "eab684eb-ad06-4f97-babc-0ea51042e951", "type": "concept", "title": "Evidence citations and uncertainty"}]}]}], "dbBacked": true}$nhpj