update public.learning_paths
set
  title = 'Nutrition for Health and Performance',
  goal = 'Nutrition for Health and Performance',
  summary = 'This course teaches nutrition as an applied health and performance science for kinesiology students. Learners examine energy metabolism, macronutrients, micronutrients, hydration, nutrient timing, supplements, body composition, weight management, special populations, and eating-disorder risk while practicing evidence-based, ethical, culturally responsive communication. The course emphasizes practical decision-making: assess context, interpret evidence, protect health, support training adaptation, and know when referral is required.',
  data = $nhpjson${"slug": "nutrition-for-health-and-performance", "title": "Nutrition for Health and Performance", "description": "This course teaches nutrition as an applied health and performance science for kinesiology students. Learners examine energy metabolism, macronutrients, micronutrients, hydration, nutrient timing, supplements, body composition, weight management, special populations, and eating-disorder risk while practicing evidence-based, ethical, culturally responsive communication. The course emphasizes practical decision-making: assess context, interpret evidence, protect health, support training adaptation, and know when referral is required.", "topics": [{"id": "85a6d784-fc8f-492e-acf0-4ddb05ef0172", "type": "topic", "title": "Nutrition Science, Evidence Appraisal, and Scope of Practice", "description": "Students start by learning how nutrition knowledge is made, interpreted, and ethically applied in kinesiology settings.", "children": [{"id": "1b69f7f7-1735-430a-8177-ba3b700ec458", "type": "subtopic", "title": "Evidence-based nutrition practice", "description": "The point is to separate strong evidence from hype before making health or performance claims.", "children": [{"id": "324af5a4-580f-4840-91b8-7ecc3e0bdfcd", "type": "concept", "title": "Hierarchy of evidence"}, {"id": "d1a45553-1d40-4398-b54a-5afa7d5f09ff", "type": "concept", "title": "Systematic reviews and position stands"}, {"id": "0e7a2715-da72-4c43-8409-6b645e29b5c0", "type": "concept", "title": "Limits of observational research"}]}, {"id": "c8416238-3099-4590-aab9-2f1de7bcee0a", "type": "subtopic", "title": "Scope, ethics, and referral", "description": "Students learn what a kinesiology professional can responsibly discuss and when a registered dietitian or clinician is needed.", "children": [{"id": "c979bcc8-8d89-4c42-b508-ea92a07db1fd", "type": "concept", "title": "Legal and professional boundaries"}, {"id": "65235b85-a7d8-42bc-bc3f-be9d819a0f59", "type": "concept", "title": "Red flags requiring referral"}, {"id": "5aa06d9e-7003-48cf-bcb3-98dcea0e0484", "type": "concept", "title": "Client autonomy and cultural respect"}]}, {"id": "445523c6-3818-42b5-86ee-3de4bbb1d47e", "type": "subtopic", "title": "Dietary assessment basics", "description": "Students learn how intake data are collected, where they fail, and how to interpret them carefully.", "children": [{"id": "c42df32c-4458-442e-8caf-16ee69f7eda5", "type": "concept", "title": "24-hour recalls and food logs"}, {"id": "a8a494f5-93c8-42c2-b51f-f5a7172ce698", "type": "concept", "title": "Portion estimation and underreporting"}, {"id": "48790311-6dce-4f71-a8b7-14ae3c41432f", "type": "concept", "title": "Diet quality screening"}]}]}, {"id": "575679b5-5d73-499f-aad8-3baccc5368a4", "type": "topic", "title": "Energy Systems, Metabolism, and Exercise Fuel Use", "description": "This topic links nutrition to bioenergetics so students understand why fueling needs differ across exercise modes and intensities.", "children": [{"id": "684efbd3-9b63-41f3-9a13-95ee0ca81663", "type": "subtopic", "title": "ATP production and substrate use", "description": "Students connect food energy to muscular work through the body's energy systems.", "children": [{"id": "6db2bf72-c20f-4d06-b69b-2834015eb0a9", "type": "concept", "title": "Phosphagen, glycolytic, and oxidative pathways"}, {"id": "9df13129-977c-4e38-bed8-479aa10fe49c", "type": "concept", "title": "Carbohydrate and fat oxidation"}, {"id": "9d954c9c-a4f6-4ba4-8ac0-880eea8c1d24", "type": "concept", "title": "Intensity-duration fuel shifts"}]}, {"id": "bfe87cfc-fb4e-408f-bad6-0fed6cbf5a76", "type": "subtopic", "title": "Metabolic flexibility and training adaptation", "description": "The gist is that training status changes how fuel is stored and used.", "children": [{"id": "b1a97bb6-611f-46ed-aad3-020823461105", "type": "concept", "title": "Mitochondrial adaptation"}, {"id": "2f2ea816-7e82-4f70-a020-3a29677ea11d", "type": "concept", "title": "Glycogen storage and sparing"}, {"id": "d0dfbb2a-d144-48aa-a77f-b92bef5810e5", "type": "concept", "title": "Fat oxidation and endurance training"}]}, {"id": "22c92310-0f73-4a7a-b3c2-1f922f857b6f", "type": "subtopic", "title": "Energy expenditure estimation", "description": "Students learn why calorie needs are estimates, not magic numbers.", "children": [{"id": "c37a5172-a125-46a4-8caf-241661d949f8", "type": "concept", "title": "Resting metabolic rate"}, {"id": "0110bf5b-723a-4210-80c6-e7a943e1c964", "type": "concept", "title": "Thermic effect of food"}, {"id": "a1d202d9-62fb-49de-b494-c17f8867f823", "type": "concept", "title": "Activity energy expenditure and wearables"}]}]}, {"id": "864615ce-4d33-447e-9147-3d18a92ef9dc", "type": "topic", "title": "Macronutrients for Health, Training, and Performance", "description": "Macronutrients are the main fuel and recovery inputs for exercise. Students learn how carbohydrate, protein, fat, and fiber support different goals.", "children": [{"id": "c9309e81-7c15-481e-9b56-d16906e9edd9", "type": "subtopic", "title": "Carbohydrate and glycogen", "description": "Students learn why carbohydrate availability is central for high-intensity work and endurance performance.", "children": [{"id": "0dbb00aa-18e4-4107-a06e-d87512456d4f", "type": "concept", "title": "Glycogen storage"}, {"id": "7fdd73a8-838e-48e2-b895-4aa8c7817cc4", "type": "concept", "title": "Daily carbohydrate targets"}, {"id": "1c5f9397-a024-40c8-bace-f5498ca79592", "type": "concept", "title": "Low-carbohydrate periodization debates"}]}, {"id": "8d2cbcfd-47f4-4dc7-8758-61a363b9133a", "type": "subtopic", "title": "Protein and tissue adaptation", "description": "Students connect amino acids to muscle repair, remodeling, and satiety.", "children": [{"id": "774181d0-d119-4b82-8022-0e79321055c1", "type": "concept", "title": "Protein quality and distribution"}, {"id": "c5eeb19d-d01a-47fe-9348-08a8339aa198", "type": "concept", "title": "Leucine and muscle protein synthesis"}, {"id": "cecf3036-4dc5-4d6c-ba92-1e1e3d5cfe8e", "type": "concept", "title": "Strength, endurance, and aging needs"}]}, {"id": "efccffd9-3568-4051-be4e-dee51bb83ec0", "type": "subtopic", "title": "Fat and fiber", "description": "Students learn to balance performance goals with heart, gut, and long-term metabolic health.", "children": [{"id": "7199ffaf-77eb-413f-93b5-09ac76e6d26c", "type": "concept", "title": "Essential fatty acids"}, {"id": "90fa60e3-1ac3-4e10-9e81-a19a52b80959", "type": "concept", "title": "Dietary fat and hormones"}, {"id": "22673781-7d6c-48bc-939c-b86cd6919c7e", "type": "concept", "title": "Fiber, gut function, and timing tradeoffs"}]}]}, {"id": "3fd70299-61a6-4637-bfca-49824ff150d6", "type": "topic", "title": "Micronutrients, Dietary Patterns, and Long-Term Health", "description": "This topic moves beyond single nutrients to sustainable eating patterns that support health, adaptation, and disease-risk reduction.", "children": [{"id": "71a4ba70-74d1-4fa9-af23-5236995b429a", "type": "subtopic", "title": "Key vitamins and minerals for active people", "description": "Students identify micronutrients most likely to affect performance, recovery, or health status.", "children": [{"id": "706a13eb-fdab-4164-99ba-84f428d9c0c7", "type": "concept", "title": "Iron, calcium, vitamin D, B vitamins, and antioxidants"}, {"id": "ec398442-21b0-4fab-bf9a-f77159a57c02", "type": "concept", "title": "Deficiency risk factors"}, {"id": "76c511be-cb50-4454-9b9c-36814d0cda8e", "type": "concept", "title": "Lab values and clinical referral"}]}, {"id": "95f1c5b4-9871-4674-b487-a71c88617ad0", "type": "subtopic", "title": "Dietary patterns and food quality", "description": "Students learn that pattern quality often matters more than isolated nutrient chasing.", "children": [{"id": "6dc8c285-be9b-4b33-a977-8e85c2a26dbc", "type": "concept", "title": "Mediterranean-style and plant-forward patterns"}, {"id": "af4ee395-c1a2-4df2-8986-d621ad3c8ab7", "type": "concept", "title": "Ultra-processed foods and nutrient density"}, {"id": "f28f1126-91e6-47a7-a017-e612919a2361", "type": "concept", "title": "Food access and affordability"}]}, {"id": "03f45b6b-fdfb-4e09-8e43-b143b9110203", "type": "subtopic", "title": "Supplement vs. food-first decisions", "description": "Students practice deciding when food is sufficient and when supplementation is evidence-based.", "children": [{"id": "5bafe8aa-fdee-403f-a96c-35114cceafa8", "type": "concept", "title": "Indications for supplementation"}, {"id": "ae895f12-f173-497b-ad11-73e18c23d4ce", "type": "concept", "title": "Dose, form, and safety"}, {"id": "2e6b6f58-9ab4-4765-81c1-431b465f2843", "type": "concept", "title": "Interaction and toxicity risks"}]}]}, {"id": "2c769344-7dc9-42d0-bced-b8c6148d1128", "type": "topic", "title": "Hydration, Electrolytes, and Thermoregulation", "description": "Hydration planning connects performance, safety, sweat losses, heat stress, and individualized strategy.", "children": [{"id": "cc0aa0e2-c9b5-4749-b173-54ef7f50549f", "type": "subtopic", "title": "Fluid balance and sweat rate", "description": "Students learn to estimate fluid needs using body mass change, sweat rate, and environment.", "children": [{"id": "b445f286-8b53-4942-a6fd-6b6b4c6d21ba", "type": "concept", "title": "Euhydration and dehydration"}, {"id": "874db4a5-da83-40ce-86a1-151677699b39", "type": "concept", "title": "Sweat testing basics"}, {"id": "3a8ecd63-0ce2-4905-bdbd-0f100d21a2ac", "type": "concept", "title": "Heat, humidity, clothing, and acclimatization"}]}, {"id": "39405c6d-29be-4dc7-b407-6c70e090f1ba", "type": "subtopic", "title": "Electrolytes and sodium strategy", "description": "Students understand when electrolytes matter and why one-size advice fails.", "children": [{"id": "4da017ab-9bf6-4703-a067-ea5d1ea04f5c", "type": "concept", "title": "Sodium losses and replacement"}, {"id": "7a96f7fa-968a-470d-b2c3-aaae57e9040d", "type": "concept", "title": "Hyponatremia risk"}, {"id": "0af18ebb-0458-49e2-9ca4-dd4839ffa326", "type": "concept", "title": "Cramps, thirst, and practical signals"}]}, {"id": "8c1c8415-3357-42bc-a52e-a0dd9abb0f2a", "type": "subtopic", "title": "Competition hydration plans", "description": "Students translate physiology into pre-, during-, and post-exercise plans.", "children": [{"id": "f0d90287-fbde-49e3-9e94-201c0d4c5b3d", "type": "concept", "title": "Prehydration"}, {"id": "e6f73025-41b9-49d2-8ab9-24b9f320051b", "type": "concept", "title": "Fluid access during events"}, {"id": "2a9d37ee-4636-42a1-8219-a20a3a8da157", "type": "concept", "title": "Rehydration after exercise"}]}]}, {"id": "250d318f-d497-4a07-a26b-4a7bac874c0f", "type": "topic", "title": "Energy Balance, Energy Availability, and RED-S", "description": "Energy balance is not just weight math; energy availability determines whether the body can train, adapt, menstruate, maintain bone, and recover.", "children": [{"id": "9d7aac3c-7f06-4dc5-abc9-81c87cdd8725", "type": "subtopic", "title": "Energy balance concepts", "description": "Students learn the difference between intake, expenditure, and the body's adaptive responses.", "children": [{"id": "01a62f0d-2838-4186-88b4-f6d1822fd352", "type": "concept", "title": "Energy intake vs. expenditure"}, {"id": "6dda5831-a9f4-4c10-b4be-3b3414c32388", "type": "concept", "title": "Adaptive thermogenesis"}, {"id": "97907d9f-3960-4f06-84d7-ce49c11d36d7", "type": "concept", "title": "Within-day energy deficits"}]}, {"id": "3f21b838-2d83-4c18-b17b-a95dbcf357c0", "type": "subtopic", "title": "Low energy availability and RED-S", "description": "Students learn how chronic underfueling harms health and performance.", "children": [{"id": "67866fa6-947b-42c7-a409-b37c9c03d241", "type": "concept", "title": "Relative Energy Deficiency in Sport"}, {"id": "4df76a37-9305-45ee-ac09-d556ee4bb157", "type": "concept", "title": "Menstrual, endocrine, bone, immune, and mood effects"}, {"id": "fbaef5b1-1810-4bf0-bf87-b65276f37040", "type": "concept", "title": "Screening and referral"}]}, 